#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    vector<int> prisonAfterNDays(vector<int>& cells, int n) {
        unordered_map<int, int> seen;
        int state = 0;

        for (int cell : cells) {
            state <<= 1;
            state |= cell;
        }

        while (n > 0) {
            if (seen.count(state)) {
                n %= seen[state] - n;
            }
            seen[state] = n;
            if (n == 0) break;
            n--;

            int nextState = 0;
            for (int i = 1; i < 7; i++) {
                nextState |= ((state >> (i - 1) & 1) == (state >> (i + 1) & 1)) << i;
            }
            state = nextState;
        }

        vector<int> result(8);
        for (int i = 7; i >= 0; i--) {
            result[i] = state & 1;
            state >>= 1;
        }
        return result;
    }
};
